	// but we:
	//  - remove the unnecessary (i % n) since 0 <= i < n
	//  - compute (i*j + c) % n iteratively to avoid a multiplication per j.
	traverser(A, B).template for_dims<'i'>([&](auto inner) {
		// inner has 'i' fixed, 'j' remaining
		auto si = inner.state(); // contains index in 'i'
		const std::size_t i = get_index<'i'>(si);

		// x[i] — x is indexed by 'j', so we use j = i
		x[idx<'j'>(i)] = static_cast<num_t>(i) * inv_n;

		// Recurrences for:
		//   A[i][j] = ((i*j + 1) % n) / n
		//   B[i][j] = ((i*j + 2) % n) / n
		//
		// For fixed i and j increasing by 1:
		//   (i*(j+1) + c) % n = ( (i*j + c) + i ) % n
		// so we can avoid the multiply i*j and just add i each time.
		std::size_t a_val = 1 % n; // current value of (i*j + 1) % n
		std::size_t b_val = 2 % n; // current value of (i*j + 2) % n

