			// s has both 'i' and 'j', j increases in-order here

			A[s] = static_cast<num_t>(a_val) * inv_n;
			B[s] = static_cast<num_t>(b_val) * inv_n;

			// Advance the recurrences:
			// a_val = (a_val + i) % n
			// b_val = (b_val + i) % n
			a_val += i;
			if (a_val >= n) a_val -= n;

			b_val += i;
			if (b_val >= n) b_val -= n;
		});
	});
