			// s has both 'i' and 'j'
			// x is indexed only by 'j', but additional dimensions in 's'
			// are ignored by Noarr, so x[s] is valid and avoids building
			// a separate state object.
			const num_t xj = x[s];

			tmp_i += A[s] * xj;
			y_i   += B[s] * xj;
		});

		// Write back results for this i
		tmp[si] = tmp_i;
		y[si]   = alpha * tmp_i + beta * y_i;
	});
