	traverser(A, B, tmp, x, y).template for_dims<'i'>([=](auto inner) {
		// inner has 'i' fixed, 'j' remaining
		auto si = inner.state(); // state with fixed 'i' (row index)

		// Per-row accumulators kept in registers; this replaces
		// repeatedly loading/storing tmp[i] and y[i] inside the j-loop.
		num_t tmp_i = (num_t)0.0;
		num_t y_i   = (num_t)0.0;

		// Inner loop over all columns 'j' for this fixed row 'i'
		inner.for_each([&](auto s) {
			// s has both 'i' and 'j'
			//
			// x is indexed only by 'j', but it safely accepts a state with
			// extra dimensions — the 'i' part is ignored — so we can use x[s]
			// directly and avoid creating a separate state for j.
			const num_t xj = x[s];

			// Accumulate A[i][j] * x[j] and B[i][j] * x[j]
			tmp_i += A[s] * xj;
			y_i   += B[s] * xj;
		});

		// Store the accumulated dot products
		tmp[si] = tmp_i;

		// Final combination:
		//   y[i] = alpha * tmp[i] + beta * y[i]
		// computed once per row after all j have been processed.
		y[si] = alpha * tmp_i + beta * y_i;
	});
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;
	using namespace noarr;

	// problem size
	std::size_t n = N;

	// scalars
	num_t alpha;
	num_t beta;

	// common lengths for dimensions 'i' and 'j'
	auto set_lengths =
		set_length<'i'>(n) ^
		set_length<'j'>(n);

	// data structures
	auto A   = bag(scalar<num_t>() ^ mat_layout ^ set_lengths);
	auto B   = bag(scalar<num_t>() ^ mat_layout ^ set_lengths);
	auto tmp = bag(scalar<num_t>() ^ y_layout   ^ set_lengths); // length N in 'i'
	auto x   = bag(scalar<num_t>() ^ x_layout   ^ set_lengths); // length N in 'j'
	auto y   = bag(scalar<num_t>() ^ y_layout   ^ set_lengths); // length N in 'i'

	// initialize data
	init_array(alpha, beta, A.get_ref(), B.get_ref(), x.get_ref());

	// timing
	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_gesummv(alpha, beta,
	               A.get_ref(), B.get_ref(),
	               tmp.get_ref(), x.get_ref(), y.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// optional: print results (to prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		serialize_data(std::cerr, y.get_ref() ^ hoist<'i'>());
	}

	// print elapsed time
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
