// computation kernel
//
// Optimizations over the original version:
//
// 1. Row-wise accumulation in registers:
//    - Instead of repeatedly reading and writing tmp[i] and y[i] inside
//      the inner j-loop, we keep per-row accumulators (tmp_i, y_i) in
//      registers and store them once per row. This reduces memory traffic
//      and enables better instruction-level optimization (FMA, etc.).
//
// 2. Cheaper x access:
//    - We use x[s] directly. The state `s` has dimensions ('i','j'),
//      but x is only indexed by 'j'. Noarr ignores the extra 'i'
//      dimension, so this avoids constructing a separate state idx<'j'>(j)
//      every iteration.
//
// 3. Parallelization over rows with OpenMP:
//    - We use a range-based loop over a traverser to iterate the outer
//      'i' dimension and apply `#pragma omp parallel for`. Each iteration
//      operates on a distinct row, so there are no data races.
//    - The OpenMP schedule chunk size is controlled by a constexpr
//      tuning parameter GESUMMV_OMP_CHUNK.
//
// 4. Data locality preserved:
//    - We still traverse A and B row-by-row (‘i’ outer, ‘j’ inner), which
//      matches the row-major layout (j is the innermost/contiguous dim).
//
[[gnu::flatten, gnu::noinline]]
void kernel_gesummv(num_t alpha, num_t beta, auto A, auto B, auto tmp, auto x, auto y) {
	using namespace noarr;

	// Tuning parameter: number of rows (iterations) per thread chunk in
	// the outer parallel loop. Can be adjusted for a given machine.
	constexpr int GESUMMV_OMP_CHUNK = 8;

	// Traverser over all structures; the top-level dimension is 'i'
	// (rows), and 'j' is the inner/contiguous dimension.
	auto trav = traverser(A, B, tmp, x, y);

	// Row kernel: computes one row i (fixed 'i', iterates over 'j')
	// using a generic lambda so the compiler can inline it for each
	// traverser type.
	auto compute_row = [&](auto inner) {
		// inner has 'i' fixed, 'j' remaining
		auto si = inner.state(); // state with fixed 'i'

		// Per-row accumulators in registers
		num_t tmp_i = (num_t)0.0;
		num_t y_i   = (num_t)0.0;

		// Inner loop over 'j'
		inner.for_each([&](auto s) {
			// s has both 'i' and 'j'
			// x is indexed only by 'j', extra 'i' is ignored by Noarr
			const num_t xj = x[s];

			// Accumulate products in registers
			tmp_i += A[s] * xj;
			y_i   += B[s] * xj;
		});

		// Write back results for this row:
		// tmp[i]  = accumulated tmp_i
		// y[i]    = alpha * tmp[i] + beta * y[i]
		tmp[si] = tmp_i;
		y[si]   = alpha * tmp_i + beta * y_i;
	};

	// Original C:
	// for (i = 0; i < _PB_N; i++) {
	//   tmp[i] = 0.0;
