	#pragma scop
	#ifdef _OPENMP
	// Parallelize over rows ('i') using a traverser range. Each
	// `inner` traverser instance corresponds to one fixed row i.
	#pragma omp parallel for schedule(static, GESUMMV_OMP_CHUNK)
	for (auto inner : trav) {
		compute_row(inner);
	}
	#else
	// Serial fallback if OpenMP is not enabled.
	for (auto inner : trav) {
		compute_row(inner);
	}
	#endif
	#pragma endscop
}

